{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The rescue team gathers at the edge of the ruined city.",
      "visual_description": "A cracked hilltop overlooking a broken skyline of toppled towers and torn royal banners; lantern light pools around the team as fog rolls in.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 2,
      "caption": "Mara unrolls a map marked with red warnings.",
      "visual_description": "An ink-stained map spread on a stone, brass compass spinning oddly, red Xs over castle gates and cursed towers.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp warns of three temptations ahead.",
      "visual_description": "Close-up of the lamp's single flame-eye glowing wide, casting three flickering shadows shaped like a gate, a tower, and a bridge.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "The tin fox scouts a cracked side street.",
      "visual_description": "A small clockwork fox with blue glass eyes trots through rubble; its key-wind tail ticks softly past fallen royal banners.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The glass diver emerges from a shattered shop window.",
      "visual_description": "A figure in a clear diving helmet steps headfirst through a tall broken window as if surfacing from water, coat shimmering with reflected city lights.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "The team meets at a fountain of black water.",
      "visual_description": "A cracked stone fountain spilling dark water in moonlight; the four figures circle it, reflections rippling strangely.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "They find the sleeping tax collector slumped at a checkpoint.",
      "visual_description": "An old wooden checkpoint booth; a plump official snores on a ledger pillow with stamped papers stuck to his sleeves and cheek.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "Mara questions him, but he only mumbles in his sleep.",
      "visual_description": "Mara leans in with her compass while the official drools onto a stamped form; the tin fox tilts its head in disbelief.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "The oracle lamp shouts about an approaching patrol.",
      "visual_description": "The lamp's flame flares bright orange; armored shadows in plumed helmets march in the distance between collapsed columns.",
      "characters": ["oracle_lamp", "mara_guess_placeholder"]
    },
    {
      "scene_number": 10,
      "caption": "The glass diver hides the team inside a tall mirror.",
      "visual_description": "A gilded standing mirror in an alley ripples like a pond as the diver pulls the others through; only the tin fox's tail still sticks out.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "Inside the mirror they drift past reflected ruins.",
      "visual_description": "A silvery underwater-like world where upside-down towers float; the team swims through cold reflected light.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "The tin fox sniffs out a hidden magic door.",
      "visual_description": "A low door carved with spiral runes set into a mossy wall; the clockwork fox paws at its glowing keyhole.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "The oracle lamp recites the door's true name.",
      "visual_description": "The lamp's eye narrows to a slit, syllables curling from its flame in glowing script that the door drinks in.",
      "characters": ["oracle_lamp", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "They find the captive chained inside a cursed tower room.",
      "visual_description": "A circular chamber with peeling royal murals; the sleeping tax collector is again slumped here, chained to a stamping desk, snoring loudly.",
      "characters": ["sleeping_tax_collector", "glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "Mara realizes the dozing official is the one they came to save.",
      "visual_description": "Mara holds up a portrait sketch matching the snoring man's face; her expression is half exasperation, half relief.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "The glass diver dives them all into a tall arched window.",
      "visual_description": "A stained-glass window ripples like water as the diver pulls the chained sleeper through; the tin fox leaps after, tail winding.",
      "characters": ["glass_diver", "sleeping_tax_collector", "tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 17,
      "caption": "They sprint across a crumbling bridge as stones fall behind.",
      "visual_description": "A long stone bridge over a misty chasm; banners trail from broken railings as the team runs, the official dragged on his ledger like a sled.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far side, the lamp grins and the tax collector keeps snoring.",
      "visual_description": "Dawn light spills over a quiet meadow beyond the bridge; Mara folds her map, the diver removes the helmet's clasp, the tin fox curls up, and the official sleeps on.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

